import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import {createHash} from 'node:crypto';
const runnerPath='docs/phase-plans/verify-phase002.mjs';
const original=fs.readFileSync(runnerPath,'utf8');
const hashBytes=value=>createHash('sha256').update(value).digest('hex');
const frozenReviewPath='docs/evidence/attempts/Phase002/attempt-4/review.json';
const frozenReviewHash='872ea77c344211b84a2bced9aa65377e44049394ca5d5a5ae31828066e4f5858';
assert(original.includes("const frozenReviewPath = '"+frozenReviewPath+"';"));
assert(original.includes("const frozenReviewHash = '"+frozenReviewHash+"';"));
const start=original.indexOf('function checkWhitespacePolicy(root) {');
const end=original.indexOf('\nfunction checkGitWhitespace(root)',start);
assert(start>=0&&end>start);
const predicateSource=original.slice(start,end);
const overlay=new Map();
const bytes=(root,file)=>overlay.get(file)??fs.readFileSync(path.join(root,file));
const text=(root,file)=>bytes(root,file).toString('utf8').replace(/^\uFEFF/,'');
const hash=(root,file)=>hashBytes(bytes(root,file));
const json=(root,file)=>JSON.parse(text(root,file));
const requireThat=(condition,code,message=code)=>assert(condition,code+': '+message);
const evaluate=new Function('assert','text','hash','json','bytes','frozenReviewPath','frozenReviewHash','requireThat',predicateSource+'\nreturn checkWhitespacePolicy;');
const check=evaluate(assert,text,hash,json,bytes,frozenReviewPath,frozenReviewHash,requireThat);
const root=process.cwd();
const attrs=fs.readFileSync('.gitattributes');
const review=fs.readFileSync(frozenReviewPath);
assert.equal(hashBytes(review),frozenReviewHash);
const baseline=check(root);
const observations=[{name:'exact-frozen-file-and-rule-control',outcome:'PASS',actual:baseline}];
const rule=frozenReviewPath+' whitespace=-blank-at-eof';
const cases=[
 ['broaden-to-all-json','.gitattributes',Buffer.from(attrs.toString('utf8').replace(rule,'*.json whitespace=-blank-at-eof')),'FROZEN_EVIDENCE_WHITESPACE_SCOPE'],
 ['remove-specific-exception','.gitattributes',Buffer.from(attrs.toString('utf8').replace(rule,'')),'FROZEN_EVIDENCE_WHITESPACE_SCOPE'],
 ['disable-additional-whitespace-check','.gitattributes',Buffer.from(attrs.toString('utf8').replace(rule,rule+',-blank-at-eol')),'FROZEN_EVIDENCE_WHITESPACE_SCOPE'],
 ['redirect-exception-to-new-review','.gitattributes',Buffer.from(attrs.toString('utf8').replace('attempt-4/review.json whitespace','attempt-6/review.json whitespace')),'FROZEN_EVIDENCE_WHITESPACE_SCOPE'],
 ['remove-global-lf-rule','.gitattributes',Buffer.from(attrs.toString('utf8').replace('* text=auto eol=lf','* text=auto')),'FROZEN_EVIDENCE_WHITESPACE_SCOPE'],
 ['append-to-frozen-review',frozenReviewPath,Buffer.concat([review,Buffer.from(' ')]),'FROZEN_REVIEW_BYTE_HASH'],
 ['normalize-frozen-review-eof',frozenReviewPath,Buffer.from(review.toString('utf8').replace(/\n\n$/,'\n')),'FROZEN_REVIEW_BYTE_HASH'],
];
for(const [name,file,value,expectedDiagnostic]of cases){
 overlay.clear();overlay.set(file,value);let error;try{check(root);}catch(caught){error=caught;}
 assert(error instanceof assert.AssertionError,name);assert.equal(error.code,'ERR_ASSERTION');assert.equal(error.message.split('\n')[0],expectedDiagnostic,name);
 observations.push({name,outcome:'REJECTED',expectedDiagnostic,actualDiagnostic:error.message.split('\n')[0]});
}
overlay.clear();assert.deepEqual(check(root),baseline);
console.log(JSON.stringify({status:'PASS',scope:'IN_MEMORY_INDEPENDENT_FROZEN_EVIDENCE_FORMAT_RECHECK',sourcePath:runnerPath,sourceHash:hashBytes(original),attributeHash:hashBytes(attrs),frozenReviewPath,frozenReviewHash,filesystemWrites:0,subprocesses:0,caseCount:observations.length,observations,restoredBaseline:'PASS',predicateSource}));
